#!/usr/bin/env python3
from __future__ import annotations

import base64
import io
import shutil
import subprocess
import sys
import zipfile
from datetime import datetime
from pathlib import Path

DEFAULT_REPO = Path.home() / "Documents" / "my profile github " / "my final"
PAYLOAD = """"""


def choose_repo() -> Path:
    if len(sys.argv) > 1:
        return Path(sys.argv[1]).expanduser().resolve()
    cwd = Path.cwd().resolve()
    if (cwd / ".git").is_dir():
        return cwd
    return DEFAULT_REPO


def main() -> None:
    repo = choose_repo()
    if not (repo / ".git").is_dir():
        raise SystemExit(
            f"Git repository not found at: {repo}\n"
            "Run this from the portfolio repository or pass the repository path."
        )

    required_before = ["index.html", "styles.css", "script.js"]
    missing = [name for name in required_before if not (repo / name).exists()]
    if missing:
        raise SystemExit(f"Repository is missing expected files: {', '.join(missing)}")

    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    backup = repo.parent / f"my final backup {stamp}"
    backup.mkdir(parents=True, exist_ok=False)

    for name in ["index.html", "styles.css", "script.js", "README.md", "assets", ".nojekyll"]:
        source = repo / name
        if not source.exists():
            continue
        target = backup / name
        if source.is_dir():
            shutil.copytree(source, target)
        else:
            shutil.copy2(source, target)

    data = base64.b64decode(PAYLOAD)
    with zipfile.ZipFile(io.BytesIO(data)) as archive:
        for member in archive.infolist():
            if member.filename.startswith(".git/") or member.filename == ".git":
                continue
            destination = (repo / member.filename).resolve()
            if repo not in destination.parents and destination != repo:
                raise SystemExit("Unsafe path detected in embedded package.")
        archive.extractall(repo)

    checks = {
        "coursework section": 'id="coursework"',
        "grouped backend skills": "Backend & APIs",
        "published repository grid": "Published repositories",
        "September payment roadmap": "September 2026",
        "January 2027 roadmap": "By Jan 2027",
        "real profile photo": "assets/nomaan-profile.jpg",
        "signature": "about-signature",
    }

    html = (repo / "index.html").read_text(encoding="utf-8")
    all_text = "\n".join(
        (repo / name).read_text(encoding="utf-8")
        for name in ["index.html", "styles.css", "script.js", "README.md"]
    )

    failed = [label for label, token in checks.items() if token not in html]
    forbidden = [
        token for token in [
            "Current strength",
            "Open to internships",
            "AI-Assisted Development",
            "cursor-dot",
            "cursor-ring",
            "—",
            "–",
        ]
        if token in all_text
    ]

    if failed or forbidden:
        if failed:
            print("Missing validation items:", ", ".join(failed))
        if forbidden:
            print("Forbidden old content still present:", ", ".join(forbidden))
        raise SystemExit("Validation failed. Your previous files are preserved in the backup folder.")

    print("\nFinal portfolio files installed successfully.")
    print(f"Repository: {repo}")
    print(f"Backup:     {backup}")
    print("\nIncluded:")
    print("  - signature instead of the large NM decoration")
    print("  - real profile photo")
    print("  - no cursor follower")
    print("  - no em dash or en dash characters")
    print("  - no Open to internships wording")
    print("  - grouped skills without percentage bars")
    print("  - selected university coursework without grades")
    print("  - six published project repositories")
    print("  - Engineering Digest builds and major project roadmap through January 2027")
    print("  - public README and .nojekyll")

    result = subprocess.run(
        ["git", "status", "--short"], cwd=repo, text=True, capture_output=True
    )
    print("\nGit changes:")
    print(result.stdout.strip() or "No changes detected")
    print("\nNext commands:")
    print(f'cd "{repo}"')
    print('python3 -m http.server 8080')
    print('# After checking the site, press Control+C and run:')
    print('git add -A')
    print('git commit -m "Complete final portfolio content"')
    print('git push')


if __name__ == "__main__":
    main()
